// Mode switch must not clip its options: its overflow must be visible.
const modeSwitch = page.getByRole('radiogroup', { name: 'Radar mode' });
await expect(modeSwitch).toBeVisible();
await expect(modeSwitch).toHaveCSS('overflow', 'visible');

// Radar list must not clip its rows.
const radarList = page.getByRole('list', { name: 'Radar items' });
await expect(radarList).toBeVisible();
await expect(radarList).toHaveCSS('overflow', 'visible');
